/// Every route in [AppRouter], as an enum.
///
/// Useful for exhaustive switches, analytics keys and tests that need to
/// enumerate the app's locations.
enum AppRoute {
  /// [AdminRoute] at `/admin`.
  adminRoute('adminRoute', '/admin'),

  /// [BottomSheetContent] at `/content`.
  bottomSheetContent('bottomSheetContent', '/content'),

  /// [BottomSheetNextRoute] at `/next`.
  bottomSheetNext('bottomSheetNext', '/next'),

  /// [HomeRoute] at `/home-screen`.
  homeRoute('homeRoute', '/home-screen'),

  /// [ProfileTab] at `/profile`.
  profileTab('profileTab', '/profile'),

  /// [SettingsTab] at `/settings-tab`.
  settingsTab('settingsTab', '/settings-tab'),

  /// [NotificationsTab] at `/notifications`.
  notificationsTab('notificationsTab', '/notifications'),

  /// [NotificationDetail] at `/notifications/:id`.
  notificationDetail('notificationDetail', '/notifications/:id'),

  /// [NotificationActionScreen] at `/notifications/:id/action`.
  notificationActionScreen(
    'notificationActionScreen',
    '/notifications/:id/action',
  ),

  /// [SettingsRoute] at `/settings`.
  settings('settings', '/settings'),

  /// [LegacyProfileRoute] at `/account`.
  legacyProfileRoute('legacyProfileRoute', '/account'),

  /// [LoginRoute] at `/login`.
  loginRoute('loginRoute', '/login'),

  /// [NewFeatureRoute] at `/new-feature`.
  newFeatureRoute('newFeatureRoute', '/new-feature'),

  /// [OnboardingRoute] at `/onboarding`.
  onboardingRoute('onboardingRoute', '/onboarding'),

  /// [ProductDetailsRoute] at `/products/:id(\d+)`.
  productDetails('productDetails', '/products/:id(\\d+)'),

  /// [ProductOffersRoute] at `/products/:id(\d+)/offers`.
  productOffers('productOffers', '/products/:id(\\d+)/offers'),

  /// [ProductReviewsRoute] at `/products/:id(\d+)/reviews`.
  productReviews('productReviews', '/products/:id(\\d+)/reviews'),

  /// [ProductListRoute] at `/products`.
  productList('productList', '/products');

  const AppRoute(this.routeName, this.template);

  /// The route's name, as registered with go_router.
  final String routeName;

  /// The route's absolute path pattern.
  final String template;
}

/// The branches of [DashboardShell], in tab order.
///
/// Each value's [index] is the branch index go_router uses, so [go] and
/// [of] stay correct when `order:` changes.
enum DashboardShellBranch {
  /// The branch rooted at [HomeRoute].
  homeRoute('/home-screen'),

  /// The branch rooted at [ProfileRoute].
  profileShell('/profile'),

  /// The branch rooted at [SettingsRoute].
  settings('/settings');

  const DashboardShellBranch(this.initialLocation);

  /// Where this branch starts.
  final String initialLocation;

  /// The branch [shell] is showing.
  static DashboardShellBranch of(StatefulNavigationShell shell) =>
      values[shell.currentIndex];

  /// Whether [shell] is showing this branch.
  bool isActiveIn(StatefulNavigationShell shell) => shell.currentIndex == index;

  /// Switches [shell] to this branch.
  ///
  /// With [initialLocation] set, the branch also resets to where it starts —
  /// the usual response to tapping the active tab again.
  void go(StatefulNavigationShell shell, {bool initialLocation = false}) =>
      shell.goBranch(index, initialLocation: initialLocation);

  /// Switches the nearest enclosing stateful shell to this branch.
  ///
  /// For a screen *inside* the shell that has no `StatefulNavigationShell`
  /// of its own — a "see all" button that jumps to another tab.
  void goFrom(BuildContext context, {bool initialLocation = false}) =>
      StatefulNavigationShell.of(
        context,
      ).goBranch(index, initialLocation: initialLocation);
}
